//go:build arm64

package floats

// The NEON kernels of the windowed overlap-add (overlap.go), generated by go-asmgen
// (overlap_arm64_gen.go) into overlap_arm64.s: four float32 or two float64 lanes
// per step. A kernel does the blocks that fit, (n/lanes)*lanes elements of the
// n = len(a) steps, and the Go code below finishes the tail. NEON is the ARMv8-A
// baseline: no gate. No kernel keeps a pointer: go:noescape.
//
//go:noescape
func overlapWindow32NEON(dst, a, b, win []float32)

//go:noescape
func overlapWindow64NEON(dst, a, b, win []float64)

func overlapWindow32(dst, a, b, win []float32) {
	overlapWindow32NEON(dst, a, b, win)
	overlapTail32(dst, a, b, win, len(a)&^3)
}

func overlapWindow64(dst, a, b, win []float64) {
	overlapWindow64NEON(dst, a, b, win)
	overlapTail64(dst, a, b, win, len(a)&^1)
}
